```cpp
#include <iostream>
#include <fstream>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("punkty.txt");
    int n;
    plik >> n;
    int px[100], py[100];
    int sx = 0, sy = 0;
    for (int i = 0; i < n; i++) {
        plik >> px[i] >> py[i];
        sx += px[i];
        sy += py[i];
    }
    double cx = (double)sx / n;
    double cy = (double)sy / n;
    cout << fixed << setprecision(2);
    cout << "Centroid: (" << cx << ", " << cy << ")" << endl;
    double minDist = 1e18;
    int minIdx = 0;
    for (int i = 0; i < n; i++) {
        double d = sqrt((px[i] - cx) * (px[i] - cx) + (py[i] - cy) * (py[i] - cy));
        cout << "(" << px[i] << "," << py[i] << "): " << d << endl;
        if (d < minDist) {
            minDist = d;
            minIdx = i;
        }
    }
    cout << "Najblizszy centroidowi: (" << px[minIdx] << "," << py[minIdx] << "), odleglosc = " << minDist << endl;
    return 0;
}
```

**Wyjasnienie**: Centroid obliczamy jako srednia arytmetyczna wspolrzednych. Nastepnie liczymy odleglosc euklidesowa kazdego punktu od centroidu i szukamy minimum.

